for i = 1:n
    slope = slope + alpha * (y(i) - y_pred(i)) * x(i);
    intercept = intercept + alpha * (y(i) - y_pred(i));
    y_pred = slope * x + intercept;
    ss_res = sum((y - y_pred).^2);
end

% Calculate R-squared and MSE
