    cin >> n;

    while (cin.fail() || n < 1) {
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cout << "Invalid input. Please enter a positive integer: ";
        cin >> n;
    }

    int fib1 = 0, fib2 = 1, fib3;
    ofstream file("fibonacci.csv");
    file << "Fibonacci Number,Index\n";
    file << fib1 << ",0\n";
    file << fib2 << ",1\n";

    for (int i = 2; i <= n; i++) {
        fib3 = fib1 + fib2;
        file << fib3 << "," << i << "\n";
        fib1 = fib2;
        fib2 = fib3;
    }

    file.close();
    cout << "Fibonacci sequence generated and saved to fibonacci.csv." << endl;

    return 0;
}
```

