以下是一个示例Scala代码，可以将提供的消息发送给多个收件人，并处理可能出现的错误情况：

```scala
import java.util.Properties
import javax.mail.{Message, Session, Transport}
import javax.mail.internet.{InternetAddress, MimeMessage}

object EmailSender {
  def sendEmail(subject: String, message: String, recipients: List[String]): Unit = {
    val props = new Properties()
    props.put("mail.smtp.auth", "true")
    props.put("mail.smtp.starttls.enable", "true")
    props.put("mail.smtp.host", "smtp.gmail.com")
    props.put("mail.smtp.port", "587")

    val session = Session.getInstance(props, new javax.mail.Authenticator() {
      override def getPasswordAuthentication(): javax.mail.PasswordAuthentication = {
        new javax.mail.PasswordAuthentication("your_email@gmail.com", "your_password")
      }
    })

    try {
      val mimeMessage = new MimeMessage(session)
      mimeMessage.setFrom(new InternetAddress("your_email@gmail.com"))
      recipients.foreach(recipient => mimeMessage.addRecipient(Message.RecipientType.TO, new InternetAddress(recipient)))
      mimeMessage.setSubject(subject)
      mimeMessage.setText(message)

      Transport.send(mimeMessage)
    } catch {
      case e: Exception => println("Error sending email: " + e.getMessage)
    }
  }
}
```

