#include <iostream>
#include <vector>
#include <algorithm>

// 偏见检测算法
bool isBiased(std::vector<double> data) {
    double mean = std::accumulate(data.begin(), data.end(), 0.0) / data.size();
    double variance = 0.0;
    for (auto d : data) {
        variance += (d - mean) * (d - mean);
    }
    variance /= data.size();
    return variance > 0.1;
}

// 道德决策框架
enum class Decision {
    ALLOW,
    DENY,
    REVIEW
};

Decision makeDecision(std::vector<double> data) {
    if (isBiased(data)) {
        return Decision::REVIEW;
    } else {
        return Decision::ALLOW;
    }
}

