以下是一个简单的计算器程序示例，可以进行基本的加减乘除运算和取模操作：
```
#include <stdio.h>
int main()
{
    float num1, num2, result;
    char operator;
    printf("Enter an expression: ");
    scanf("%f %c %f", &num1, &operator, &num2);
    switch (operator) {
        case '+':
            result = num1 + num2;
            break;
        case '-':
            result = num1 - num2;
            break;
        case '*':
            result = num1 * num2;
            break;
        case '/':
            if (num2 == 0) {
                printf("Error: division by zero\n");
                return 1;
            } else {
                result = num1 / num2;
            }
            break;
        case '%':
            if (num2 == 0) {
                printf("Error: division by zero\n");
                return 1;
            } else {
                result = (int)num1 % (int)num2;
            }
            break;
        default:
            printf("Error: invalid operator\n");
            return 1;
    }
    printf("Result: %f\n", result);
    return 0;
}
```
在程序中，首先提示用户输入一个表达式，例如“3 + 4”，然后用scanf函数读取用户输入，将第一个数字存储在num1变量中，运算符保存在operator变量中，第二个数字存储在num2变量中。
然后用switch语句根据运算符计算结果，如果运算符是“+”、“-”、“*”或“/”，分别执行相应的加减乘除运算，如果运算符是“%”，则先判断除数是否为0，如果不是，则将两个数强制转换为整数后进行取模运算。
最后将计算结果输出给用户。
在程序中还包括一些错误处理，例如如果除数为0则会提示用户“division by zero”并退出程序。如需进行其他操作可根据需要扩展代码。

