const express = require('express');
const app = express();
// 模拟商品数据，每个商品包含id, name, category, price等字段
const products = [
  {id: 1, name: '商品1', category: '分类1', price: 100},
  {id: 2, name: '商品2', category: '分类1', price: 200},
  {id: 3, name: '商品3', category: '分类2', price: 150},
  {id: 4, name: '商品4', category: '分类2', price: 120},
  {id: 5, name: '商品5', category: '分类3', price: 80},
];
// 搜索商品接口，可以根据关键词、价格区间、分类等条件进行搜索
app.get('/api/products/search', (req, res) => {
  const { keyword, minPrice, maxPrice, category } = req.query;
  let results = products;
  if (keyword) {
    results = results.filter(p => p.name.indexOf(keyword) >= 0);
  }
  if (minPrice) {
    results = results.filter(p => p.price >= minPrice);
  }
  if (maxPrice) {
    results = results.filter(p => p.price <= maxPrice);
  }
  if (category) {
    results = results.filter(p => p.category === category);
  }
  res.json(results);
});
// 根据价格进行升序或降序排序
app.get('/api/products/sort', (req, res) => {
  const { sortType } = req.query;
  let results = products;
  if (sortType === 'asc') {
    results = results.sort((a, b) => a.price - b.price);
  } else if (sortType === 'desc') {
    results = results.sort((a, b) => b.price - a.price);
  }
  res.json(results);
});
app.listen(3000, () => console.log('server running on port 3000'));
```
以上示例代码实现了两个接口，分别为搜索商品接口（`/api/products/search`）和排序商品接口（`/api/products/sort`）。搜索接口根据输入的关键词、价格区间、分类等条件进行过滤；排序接口根据输入的排序方式（升序或降序）进行排序。在具体的项目中，可以根据实际需求进行扩展和优化。

