} else if (userPrefersLoud()) {
  // 用户喜欢响亮，增加被动噪声抵消的强度
  passive += 5;
}

// 更新数据库中的噪声抵消设置
const updateQuery = `UPDATE settings SET active = ${active}, passive = ${passive} WHERE user_id = ${userId}`;
await db.query(updateQuery);
```

