using System;

class Program {
    static void Main(string[] args) {
        // 输入消息
        Console.Write("请输入消息：");
        string message = Console.ReadLine();

        // 删除空格和标点符号
        string cleanedMessage = "";
        foreach (char c in message) {
            if (Char.IsLetter(c)) {
                cleanedMessage += c;
            }
        }

        // 分组并颠倒顺序
        string groupedMessage = "";
        for (int i = 0; i < cleanedMessage.Length; i += 2) {
            if (i + 1 < cleanedMessage.Length) {
                groupedMessage += cleanedMessage[i + 1];
            }
            groupedMessage += cleanedMessage[i];
        }

        // 编码并保留大小写
        string[] words = groupedMessage.Split(' ');
        string encodedMessage = "";
        foreach (string word in words) {
            string encodedWord = "";
            foreach (char c in word) {
                if (Char.IsUpper(c)) {
                    encodedWord += Char.ToUpper(word[word.Length - 1 - word.IndexOf(c)]);
                } else {
                    encodedWord += word[word.Length - 1 - word.IndexOf(c)];
                }
            }
            encodedMessage += encodedWord + " ";
        }

        // 输出加密消息
        Console.WriteLine("加密消息：" + encodedMessage.Trim());
    }
