```c++
#include <iostream>
int main() {
  // Item A的输入数据
  double original_price_item_a = 100;
  double discount_item_a = 0.10;
  double profit_margin_item_a = 0.20;
  int units_sold_item_a = 20;
  // Item B的输入数据
  double original_price_item_b = 50;
  double discount_item_b = 0.20;
  double profit_margin_item_b = 0.15;
  int units_sold_item_b = 50;
  // Item A的计算
  double discounted_price_item_a = original_price_item_a * (1 - discount_item_a);
  double profit_per_unit_item_a = discounted_price_item_a * profit_margin_item_a;
  double revenue_generated_item_a = (discounted_price_item_a + profit_per_unit_item_a) * units_sold_item_a;
  // Item B的计算
  double discounted_price_item_b = original_price_item_b * (1 - discount_item_b);
  double profit_per_unit_item_b = discounted_price_item_b * profit_margin_item_b;
  double revenue_generated_item_b = (discounted_price_item_b + profit_per_unit_item_b) * units_sold_item_b;
  // 计算总收入
  double total_revenue_generated = revenue_generated_item_a + revenue_generated_item_b;
  // 输出总收入
