如何使用Go代码自动化将负面短语转换为正面短语，使用Excel表格？
假设Excel表格已保存为CSV文件，可以使用以下Go代码读取CSV文件，提示用户输入负面短语，并输出相应的正面短语：

```
package main
import (
    "encoding/csv"
    "fmt"
    "os"
)
func main() {
    file, err := os.Open("phrases.csv")
    if err != nil {
        fmt.Println("Error opening file:", err)
        return
    }
    defer file.Close()
    reader := csv.NewReader(file)
    reader.FieldsPerRecord = -1
    records, err := reader.ReadAll()
    if err != nil {
        fmt.Println("Error reading file:", err)
        return
    }
    fmt.Print("Enter a negative phrase: ")
    var phrase string
    fmt.Scanln(&phrase)
    for _, record := range records {
        if record[0] == phrase {
            fmt.Println("The corresponding positive phrase is:", record[1])
            return
        }
    }
    fmt.Println("Sorry, no corresponding positive phrase found.")
}
```

