import React, { useState, useEffect } from 'react';
import axios from 'axios';
function Table() {
  // 定义初始状态和修改状态的方法
  const [data, setData] = useState([]);
  const [sortedColumn, setSortedColumn] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  // 当组件挂载时进行数据请求
  useEffect(() => {
    axios.get('/data').then(response => {
      setData(response.data);
    });
  }, []);
  // 根据排序列和排序方式进行数组排序
  function sortData(data, column, direction) {
    if (!column) return data;
    const sortOrder = direction === 'asc' ? 1 : -1;
    return data.sort((a, b) => {
      if (a[column] < b[column]) return -1 * sortOrder;
      if (a[column] > b[column]) return sortOrder;
      return 0;
    });
  }
  // 根据搜索词进行数据过滤
  function filterData(data, searchTerm) {
    return data.filter(item =>
      Object.values(item).some(value =>
        value.toLowerCase().includes(searchTerm.toLowerCase())
      )
    );
  }
  // 在渲染表格前，根据排序和搜索条件对数据进行处理
  const sortedData = sortData(data, sortedColumn, 'asc');
  const filteredData = filterData(sortedData, searchTerm);
  return (
    <div>
      <input
        type="text"
        value={searchTerm}
        onChange={e => setSearchTerm(e.target.value)}
        placeholder="Search"
      />
      <table>
        <thead>
          <tr>
            <th onClick={() => setSortedColumn('id')}>
              ID{sortedColumn === 'id' ? `[${direction === 'asc' ? '↓' : '↑'}]` : ''}
            </th>
            <th onClick={() => setSortedColumn('name')}>
              Name{sortedColumn === 'name' ? `[${direction === 'asc' ? '↓' : '↑'}]` : ''}
            </th>
            <th onClick={() => setSortedColumn('age')}>
              Age{sortedColumn === 'age' ? `[${direction === 'asc' ? '↓' : '↑'}]` : ''}
            </th>
          </tr>
        </thead>
        <tbody>
          {filteredData.map(item => (
            <tr key={item.id}>
              <td>{item.id}</td>
              <td>{item.name}</td>
              <td>{item.age}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
export default Table;
