const string LOCATION = "Manhattan";
const string SORT_BY = "rating";
const int LIMIT = 5;

// 价格范围
const string PRICE = "2,3";

// 执行HTTP GET请求并返回响应
string httpGet(string url, string authHeader) {
    CURL *curl;
    CURLcode res;
    string response;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, authHeader.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](char *ptr, size_t size, size_t nmemb, string *data) {
            data->append(ptr, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    }

    return response;
}

int main() {
    // 构造HTTP请求头
    string authHeader = "Authorization: Bearer " + API_KEY;

    // 构造搜索URL
    string searchUrl = SEARCH_URL + "?term=" + TERM + "&location=" + LOCATION + "&sort_by=" + SORT_BY + "&limit=" + to_string(LIMIT) + "&price=" + PRICE;

    // 执行HTTP GET请求并获取响应
    string response = httpGet(searchUrl, authHeader);

    // 解析JSON响应
    Json::Value root;
    Json::CharReaderBuilder builder;
    Json::CharReader *reader = builder.newCharReader();
    string errors;
    bool parsingSuccessful = reader->parse(response.c_str(), response.c_str() + response.size(), &root, &errors);
    delete reader;

    if (parsingSuccessful) {
        // 遍历搜索结果并输出重要信息
        for (int i = 0; i < root["businesses"].size(); i++) {
            Json::Value business = root["businesses"][i];
            cout << "Name: " << business["name"].asString() << endl;
            cout << "Address: " << business["location"]["address1"].asString() << endl;
            cout << "Phone: " << business["phone"].asString() << endl;
            cout << "Rating: " << business["rating"].asFloat() << endl;
            cout << endl;
        }
    } else {
        cout << "Failed to parse JSON response: " << errors << endl;
    }

    return 0;
}
```

