本题需要使用数据结构栈来实现，先处理括号内的表达式，再处理乘除法，最后处理加减法。具体实现如下：
```cpp
#include <iostream>
#include <stack>
#include <string>
using namespace std;
int priority(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}
int calc(int x, char op, int y) {
    if (op == '+') return x + y;
    if (op == '-') return x - y;
    if (op == '*') return x * y;
    if (op == '/') return x / y;
    return 0;
}
int main() {
    stack<int> nums;
    stack<char> ops;
    string input;
    cin >> input;
    for (int i = 0; i < input.length(); i++) {
        if (isdigit(input[i])) {  // 数字入栈
            int num = 0, j = i;
            while (j < input.length() && isdigit(input[j])) {
                num = num * 10 + (input[j] - '0');
                j++;
            }
            nums.push(num);
            i = j - 1;
        }
        else if (input[i] == '(') {  // 左括号直接入栈
            ops.push(input[i]);
        }
        else if (input[i] == ')') {  // 右括号计算括号内表达式
            while (ops.top() != '(') {  // 直到匹配到左括号
                int y = nums.top();
                nums.pop();
                int x = nums.top();
                nums.pop();
                char op = ops.top();
                ops.pop();
                nums.push(calc(x, op, y));
            }
            ops.pop();  // 弹出左括号
        }
        else {  // 运算符
            char op = input[i];
            while (!ops.empty() && ops.top() != '(' && priority(op) <= priority(ops.top())) {
                int y = nums.top();
                nums.pop();
                int x = nums.top();
                nums.pop();
                char op1 = ops.top();
                ops.pop();
                nums.push(calc(x, op1, y));
            }
            ops.push(op);
        }
    }  // end for
    while (!ops.empty()) {  // 计算最终结果
        int y = nums.top();
        nums.pop();
        int x = nums.top();
        nums.pop();
        char op = ops.top();
        ops.pop();
        nums.push(calc(x, op, y));
    }
    cout << nums.top() << endl;
    return 0;
}
```
