```
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using DiffPlex;
using DiffPlex.DiffBuilder;
using DiffPlex.DiffBuilder.Model;
using DiffPlex.Model;

namespace WpfDiffPlex
{
    public partial class MainWindow : Window
    {
        public MainWindow()
        {
            InitializeComponent();
        }

        private void Button_Click(object sender, RoutedEventArgs e)
        {
            //创建DiffBuilder对象
            var diffBuilder = new InlineDiffBuilder(new Differ());

            //获取文本内容
            string originalText = tbOriginal.Text;
            string modifiedText = tbModified.Text;

            //生成对比结果
            var difResult = diffBuilder.BuildDiffModel(originalText, modifiedText);

            //将对比结果输出到RichTextBox中
            rtbComparison.Blocks.Clear();
            foreach (var line in difResult.Lines)
            {
                var paragraph = new Paragraph();
                switch (line.Type)
                {
                    case ChangeType.Unchanged:
                        paragraph.Inlines.Add(new Run(line.Text));
                        break;
                    case ChangeType.Deleted:
                        paragraph.Inlines.AddRange(Highlight(line.Text, Brushes.Red));
                        break;
                    case ChangeType.Inserted:
                        paragraph.Inlines.AddRange(Highlight(line.Text, Brushes.Green));
                        break;
                    case ChangeType.Modified:
                        paragraph.Inlines.AddRange(Highlight(line.Text, Brushes.Blue));
                        break;
                }
                rtbComparison.Blocks.Add(paragraph);
            }
        }

        private List<Inline> Highlight(string text, SolidColorBrush brush)
        {
            return text.Select(c => new Run(c.ToString())
            {
                Background = brush
            }).Cast<Inline>().ToList();
        }
    }
}
