import (
    "bufio"
    "context"
    "io"
    "log"
    "os/exec"
    "google.golang.org/grpc"
    "google.golang.org/grpc/codes"
    "google.golang.org/grpc/status"
    pb "path/to/ansible"
)
type server struct{}
func (s *server) RunPlaybook(req *pb.PlaybookRequest, stream pb.AnsibleService_RunPlaybookServer) error {
    // 创建运行Ansible playbook的命令
    cmd := exec.Command("ansible-playbook", req.Playbook)
    // 创建一个管道来捕获命令的输出
    stdout, err := cmd.StdoutPipe()
    if err != nil {
        return status.Errorf(codes.Internal, "无法创建stdout管道：%v", err)
    }
    // 启动命令
    if err := cmd.Start(); err != nil {
        return status.Errorf(codes.Internal, "无法启动命令：%v", err)
    }
    // 创建一个扫描器逐行读取命令的输出
    scanner := bufio.NewScanner(stdout)
    // 将每行输出作为单独的响应消息发送到客户端
    for scanner.Scan() {
        if err := stream.Send(&pb.PlaybookResponse{Output: scanner.Text()}); err != nil {
            return status.Errorf(codes.Internal, "无法发送响应：%v", err)
        }
    }
    // 等待命令完成
    if err := cmd.Wait(); err != nil {
        // 如果命令失败，则返回错误
        if exitErr, ok := err.(*exec.ExitError); ok {
            return status.Errorf(codes.Internal, "命令失败：%s", exitErr.Stderr)
        }
        return status.Errorf(codes.Internal, "无法等待命令：%v", err)
    }
    return nil
}
func main() {
    // 创建一个gRPC服务器并注册我们的服务
    grpcServer := grpc.NewServer()
    pb.RegisterAnsibleServiceServer(grpcServer, &server{})
    // 开始监听传入的连接
    lis, err := net.Listen("tcp", ":50051")
    if err != nil {
        log.Fatalf("无法监听：%v", err)
    }
    // 启动服务器
    if err := grpcServer.Serve(lis); err != nil {
        log.Fatalf("无法启动服务器：%v", err)
    }
}
```

在这个实现中，我们定义了一个名为`server`的结构体，该结构体实现了`AnsibleService`服务。
`RunPlaybook`方法接受一个`PlaybookRequest`消息和一个`AnsibleService_RunPlaybookServer`流，我们可以使用该流向客户端发送多个`PlaybookResponse`消息。
我们创建一个新的`exec.Command`来使用请求中指定的playbook运行`ansible-playbook`命令。然后，我们创建一个管道来捕获命令的输出。
我们启动命令并创建一个扫描器逐行读取命令的输出。我们使用`stream.Send()`方法将每行输出作为单独的`PlaybookResponse`消息发送到客户端。
命令完成后，我们检查它是否失败并在必要时返回错误。
最后，我们创建一个gRPC服务器，将我们的服务注册到其中，并开始在端口50051上监听传入的连接。
要使用此服务，您可以创建一个golang客户端，调用`RunPlaybook`方法并读取`PlaybookResponse`消息的流：

```go
package main
import (
    "context"
    "log"
    "google.golang.org/grpc"
    pb "path/to/ansible"
)
func main() {
    // 拨号gRPC服务器
    conn, err := grpc.Dial(":50051", grpc.WithInsecure())
    if err != nil {
        log.Fatalf("无法连接：%v", err)
    }
    defer conn.Close()
    // 为AnsibleService创建一个客户端
    client := pb.NewAnsibleServiceClient(conn)
    // 创建一个具有10秒超时的上下文
    ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()
    // 创建一个请求以运行playbook
    req := &pb.PlaybookRequest{Playbook: "/path/to/playbook.yml"}
    // 调用RunPlaybook方法并读取响应流
    stream, err := client.RunPlaybook(ctx, req)
    if err != nil {
        log.Fatalf("无法调用RunPlaybook：%v", err)
    }
    for {
        res, err := stream.Recv()
        if err == io.EOF {
            break
        }
        if err != nil {
            log.Fatalf("无法接收响应：%v", err)
        }
        log.Printf("输出：%s", res.Output)
    }
}
```

在这个客户端中，我们首先拨号gRPC服务器并为`AnsibleService`创建一个客户端。我们创建一个具有10秒超时和一个带有playbook路径的`PlaybookRequest`。
然后，我们调用`RunPlaybook`方法并使用for循环读取`PlaybookResponse`消息的流。我们将每行输出记录到控制台。
