```
public static void main(String[] args) {
    Vertex v1 = new Vertex("1", "City1");
    Vertex v2 = new Vertex("2", "City2");
    Vertex v3 = new Vertex("3", "City3");
    Vertex v4 = new Vertex("4", "City4");
    Vertex v5 = new Vertex("5", "City5");
    Vertex v6 = new Vertex("6", "City6");

    List<Vertex> vertexes = new ArrayList<>();
    vertexes.add(v1);
    vertexes.add(v2);
    vertexes.add(v3);
    vertexes.add(v4);
    vertexes.add(v5);
    vertexes.add(v6);

    List<Edge> edges = new ArrayList<>();
    edges.add(new Edge("1", v1, v2, 10));
    edges.add(new Edge("2", v1, v3, 20));
    edges.add(new Edge("3", v2, v4, 30));
    edges.add(new Edge("4", v2, v5, 40));
    edges.add(new Edge("5", v3, v6, 50));
    edges.add(new Edge("6", v4, v6, 60));
    edges.add(new Edge("7", v5, v6, 70));

    Graph graph = new Graph(vertexes, edges);
    DijkstraAlgorithm dijkstra = new DijkstraAlgorithm(graph);
    dijkstra.execute(v1);
    LinkedList<Vertex> path = dijkstra.getPath(v6);

    System.out.println("Path: " + path);
}
```

