```java
@Autowired
private MongoTemplate mongoTemplate;
public WebClient getWebClient() {
  ApiDetail apiDetail = mongoTemplate.findOne(Query.query(Criteria.where("id").is("apiId")), ApiDetail.class);
  WebClient.Builder builder = WebClient.builder().baseUrl(apiDetail.getApiUrl());
  if (apiDetail.getUsername() != null && apiDetail.getPassword() != null) {
    builder = builder.defaultHeader("Authorization", getAuthHeader(apiDetail.getUsername(), apiDetail.getPassword()));
  }
  return builder.build();
}
public String getAuthHeader(String username, String password) {
  String auth = username + ":" + password;
  byte[] encodedAuth = Base64.encodeBase64(auth.getBytes(StandardCharsets.US_ASCII));
  return "Basic " + new String(encodedAuth);
}
