由于需要解析HTML标记和防止SQL注入，建议使用现成的库来处理字符串。以下是Python的示例代码：

import re
from html.parser import HTMLParser

class MyHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_tag = False
        self.result = ""

    def handle_starttag(self, tag, attrs):
        self.in_tag = True
        self.result += "<" + tag + ">"

    def handle_endtag(self, tag):
        self.in_tag = False
        self.result += "</" + tag + ">"

    def handle_data(self, data):
        if self.in_tag:
            self.result += data
        else:
            self.result += self.remove_at_sign(data)

    def remove_at_sign(self, data):
        return re.sub(r"(?<![a-zA-Z0-9])@(?![a-zA-Z0-9])", "", data)

def process_string(input_str):
    # Check for SQL injection attempts
    if re.search(r"(?i)(drop|delete|insert|update|truncate|create|alter|rename|grant|revoke|commit|rollback)", input_str):
        return "Error: SQL injection attempt detected."

    # Parse HTML tags and remove @ signs
    parser = MyHTMLParser()
    parser.feed(input_str)
    result_str = parser.result

    # Truncate result string if necessary
    if len(result_str) > 100:
        result_str = result_str[:100]

    return result_str

# Example usage
input_str = "My email is john@example.com and my phone number is 123-456-7890. Don't forget to follow me on Twitter @johnsmith!"
output_str = process_string(input_str)
print(output_str)  # "My email is john@example.com and my phone number is 123-456-7890. Don't forget to follow me on Twitter johnsmith!"

