以下是使用C语言设计的相应数据结构和实现代码：

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_JOBS 20
#define MAX_MEMORY 1024
#define MAX_RESOURCE_A 20
#define MAX_RESOURCE_B 8
#define MAX_RESOURCE_C 12
#define TIME_QUANTUM 10

// 数据结构定义

// 作业
typedef struct Job {
    int id;
    int memory;
    int resource_a;
    int resource_b;
    int resource_c;
    int arrival_time;
    int start_time;
    int finish_time;
    int turnaround_time;
    double weighted_turnaround_time;
} Job;

// 进程
typedef struct Process {
    int id;
    Job* job;
    int remaining_time;
} Process;

// 内存空闲块
typedef struct FreeBlock {
    int start;
    int size;
    struct FreeBlock* next;
} FreeBlock;

// 内存分区
typedef struct MemoryPartition {
    int start;
    int size;
    Job* job;
    struct MemoryPartition* next;
} MemoryPartition;

// 全局变量定义

Job job_queue[MAX_JOBS];
int job_queue_length = 0;

Process* ready_queue[MAX_JOBS];
int ready_queue_length = 0;

Process* running_process = NULL;

MemoryPartition* memory = NULL;
FreeBlock* free_list = NULL;

int remaining_resource_a = MAX_RESOURCE_A;
int remaining_resource_b = MAX_RESOURCE_B;
int remaining_resource_c = MAX_RESOURCE_C;

// 函数声明

void generate_initial_jobs();
void generate_random_resources(Job* job);
int get_total_memory_allocated();
void add_job_to_queue(Job job);
void process_arrival(int current_time);
void schedule_jobs();
void run_process(Process* process);
void release_resources(Job* job);
void print_job_info(Job job);
void print_summary();

// 主函数

int main() {
    // 生成初始作业队列
    generate_initial_jobs();

    int current_time = 0;

    // 执行作业调度和进程调度
    while (ready_queue_length != 5 || running_process != NULL) {
        // 处理作业到达事件
        process_arrival(current_time);

        // 进程调度
        if (running_process == NULL && ready_queue_length > 0) {
            running_process = ready_queue[0];
            for (int i = 1; i < ready_queue_length; i++) {
                ready_queue[i - 1] = ready_queue[i];
            }
            ready_queue_length--;
        }

        // 执行进程
        if (running_process != NULL) {
            run_process(running_process);
            current_time++;
        } else {
            current_time += TIME_QUANTUM;
        }
    }

    print_summary();

    return 0;
}

// 辅助函数

void generate_initial_jobs() {
    srand(time(0));
    for (int i = 0; i < MAX_JOBS; i++) {
        Job job;
        job.id = i + 1;
        generate_random_resources(&job);
        job.arrival_time = rand() % 100;
        job.start_time = -1;
        job.finish_time = -1;
        job.turnaround_time = -1;
        job.weighted_turnaround_time = -1.0;
        add_job_to_queue(job);
    }
}

void generate_random_resources(Job* job) {
    job->memory = rand() % (MAX_MEMORY / 2);
    job->resource_a = rand() % (remaining_resource_a / 2);
    job->resource_b = rand() % (remaining_resource_b / 2);
    job->resource_c = rand() % (remaining_resource_c / 2);
}

int get_total_memory_allocated() {
    MemoryPartition* current = memory;
    int total_allocated = 0;
    while (current != NULL) {
        total_allocated += current->size;
        current = current->next;
    }
    return total_allocated;
}

void add_job_to_queue(Job job) {
    job_queue[job_queue_length++] = job;
}

void process_arrival(int current_time) {
    for (int i = 0; i < job_queue_length; i++) {
        if (job_queue[i].arrival_time == current_time) {
            Process* process = (Process*) malloc(sizeof(Process));
            process->id = job_queue[i].id;
            process->job = &job_queue[i];
            process->remaining_time = job_queue[i].memory;
            ready_queue[ready_queue_length++] = process;
        }
    }
}

void schedule_jobs() {
    int remaining_memory = MAX_MEMORY - get_total_memory_allocated();
    for (int i = 0; i < ready_queue_length && remaining_memory > 0; i++) {
        if (ready_queue[i]->remaining_time <= remaining_memory) {
            MemoryPartition* partition = (MemoryPartition*) malloc(sizeof(MemoryPartition));
            partition->start = get_total_memory_allocated();
            partition->size = ready_queue[i]->remaining_time;
            partition->job = ready_queue[i]->job;
            partition->next = NULL;

            if (memory == NULL) {
                memory = partition;
            } else {
                MemoryPartition* current = memory;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = partition;
            }

            remaining_memory -= partition->size;
        }
    }
}

void run_process(Process* process) {
    if (process->remaining_time <= TIME_QUANTUM) {
        process->job->finish_time = process->job->arrival_time +
            process->job->turnaround_time;
        process->job->weighted_turnaround_time = (double) process->job->turnaround_time /
            process->job->memory;
        release_resources(process->job);
        free(process);
        running_process = NULL;
    } else {
        process->remaining_time -= TIME_QUANTUM;
        ready_queue[ready_queue_length++] = process;

        if (memory != NULL && memory->job == process->job) {
            memory->start += TIME_QUANTUM;
            memory->size -= TIME_QUANTUM;

            if (memory->size == 0) {
                MemoryPartition* temp = memory;
                memory = memory->next;
                free(temp);
            }
        }
    }
}

void release_resources(Job* job) {
    remaining_resource_a += job->resource_a;
    remaining_resource_b += job->resource_b;
    remaining_resource_c += job->resource_c;
    job->resource_a = 0;
    job->resource_b = 0;
    job->resource_c = 0;

    MemoryPartition* current = memory;
    MemoryPartition* previous = NULL;

    while (current != NULL) {
        if (current->job == job) {
            break;
        }
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL) {
            memory = memory->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
}

void print_job_info(Job job) {
    printf("Job ID: %d\n", job.id);
    printf("Memory: %d\n", job.memory);
    printf("Resource A: %d\n", job.resource_a);
    printf("Resource B: %d\n", job.resource_b);
    printf("Resource C: %d\n", job.resource_c);
    printf("Arrival Time: %d\n", job.arrival_time);
    printf("Start Time: %d\n", job.start_time);
    printf("Finish Time: %d\n", job.finish_time);
    printf("Turnaround Time: %d\n", job.turnaround_time);
    printf("Weighted Turnaround Time: %.2f\n", job.weighted_turnaround_time);
    printf("\n");
}

void print_summary() {
    printf("Job Information Summary:\n");
    for (int i = 0; i < MAX_JOBS; i++) {
        printf("Job %d:\n", job_queue[i].id);
        print_job_info(job_queue[i]);
    }
}
