[Go代码]代码：
func getData() ([]map[string]string, error) {
    db, err := sql.Open("mysql", "user:password@tcp(127.0.0.1:3306)/mydb")
    if err != nil {
        return nil, err
    }
    defer db.Close()
    rows, err := db.Query("SELECT name, age, location FROM mytable")
    if err != nil {
        return nil, err
    }
    defer rows.Close()
    columns, err := rows.Columns()
    if err != nil {
        return nil, err
    }
    count := len(columns)
    tableData := make([]map[string]string, 0)
    values := make([]interface{}, count)
    valuePtrs := make([]interface{}, count)
    for rows.Next() {
        for i := 0; i < count; i++ {
            valuePtrs[i] = &values[i]
        }
        rows.Scan(valuePtrs...)
        entry := make(map[string]string)
        for i, col := range columns {
            var v interface{}
            val := values[i]
            b, ok := val.([]byte)
            if ok {
                v = string(b)
            } else {
                v = val
            }
            entry[col] = fmt.Sprintf("%v", v)
        }
        tableData = append(tableData, entry)
    }
    if err = rows.Err(); err != nil {
        return nil, err
    }
    return tableData, nil
}
func main() {
    http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        tableData, err := getData()
        if err != nil {
            log.Fatal(err)
        }
        for _, row := range tableData {
            fmt.Fprintf(w, "Name: %s, Age: %s, Location: %s\n", row["name"], row["age"], row["location"])
        }
    })
    log.Fatal(http.ListenAndServe(":8080", nil))
}

