        print("Circle is drawing")

class Rectangle(Shape):
    def draw(self):
        print("Rectangle is drawing")

if __name__ == '__main__':
    # 继承
    dog = Dog()
    dog.eat()
    dog.bark()

    # 封装
    person = Person("Tom", 18)
    print(person.get_name() + " is " + str(person.get_age()) + " years old")

    # 多态
    shape1 = Circle()
    shape2 = Rectangle()
    shape1.draw()
