// lib/azure-storage.js
import { BlobServiceClient } from "@azure/storage-blob";
import fcsParser from "fcsparser";
import axios from "axios";
const azureConnectionString = process.env.AZURE_STORAGE_CONNECTION_STRING;
const containerName = process.env.AZURE_CONTAINER_NAME;
export async function uploadFilesToAzure(files) {
  const blobServiceClient = BlobServiceClient.fromConnectionString(
    azureConnectionString
  );
  const containerClient = blobServiceClient.getContainerClient(containerName);
  const promises = files.map(async (file) => {
    const blockBlobClient = containerClient.getBlockBlobClient(file.name);
    await blockBlobClient.uploadData(file);
    const sasToken = await generateSasToken(blockBlobClient);
    const fileUrl = `${blockBlobClient.url}?${sasToken}`;
    const parsedFileData = await parseFcsFile(file, fileUrl);
    return parsedFileData;
  });
  return Promise.all(promises);
}
async function generateSasToken(blockBlobClient) {
  // 实现生成SAS令牌的服务器端逻辑
  // 您可以使用Azure Functions或任何服务器端语言来生成它
  const response = await axios.post("/api/generate-sas-token", {
    blobName: blockBlobClient.name,
  });
  return response.data.sasToken;
}
async function parseFcsFile(file, fileUrl) {
  const response = await axios.get(fileUrl, {
    responseType: "arraybuffer",
  });
  const arrayBuffer = response.data;
  const { header, data } = fcsParser(new Uint8Array(arrayBuffer));
  const parsedFileData = {
    fileName: file.name,
    fscSscImage: createFscSscImage(data),
    fcsHeaders: header,
  };
  return parsedFileData;
}
function createFscSscImage(data) {
