import java.io.File;
import java.io.IOException;
import java.util.Random;
import java.util.Scanner;

import org.json.simple.JSONObject;
import org.json.simple.parser.JSONParser;
import org.json.simple.parser.ParseException;

public class RandomWordGenerator {

    private static final String FILENAME = "words.json";
    private static final int WORD_LENGTH = 5;
    private static final Random RANDOM = new Random();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        JSONParser parser = new JSONParser();
        JSONObject words = null;
        try {
            words = (JSONObject) parser.parse(new File(FILENAME));
        } catch (IOException | ParseException e) {
            System.out.println("Error reading file: " + e.getMessage());
            System.exit(1);
        }
        while (true) {
            System.out.println("Enter a command (generate, define, search, exit):");
            String command = scanner.nextLine();
            if (command.equals("generate")) {
                String word = generateWord();
                System.out.println("Generated word: " + word);
                if (!words.containsKey(word)) {
                    System.out.println("Enter a definition for this word:");
                    String definition = scanner.nextLine();
                    JSONObject entry = new JSONObject();
                    entry.put("word", word);
                    entry.put("definition", definition);
                    words.put(word, entry);
                    try {
                        JSONUtils.writeToFile(words, FILENAME);
                    } catch (IOException e) {
                        System.out.println("Error writing file: " + e.getMessage());
                        System.exit(1);
                    }
                    System.out.println("Word and definition saved to file.");
                } else {
                    System.out.println("Word already exists in file.");
                }
            } else if (command.equals("define")) {
                System.out.println("Enter a word to define:");
                String word = scanner.nextLine();
                JSONObject entry = (JSONObject) words.get(word);
                if (entry != null) {
                    System.out.println("Definition: " + entry.get("definition"));
                } else {
                    System.out.println("Word not found in file.");
                }
            } else if (command.equals("search")) {
                System.out.println("Enter a word to search:");
                String word = scanner.nextLine();
                JSONObject entry = (JSONObject) words.get(word);
                if (entry != null) {
                    System.out.println("Definition: " + entry.get("definition"));
                } else {
                    System.out.println("Word not found in file.");
                }
            } else if (command.equals("exit")) {
                System.out.println("Exiting program.");
                System.exit(0);
            } else {
                System.out.println("Invalid command.");
            }
        }
    }

    private static String generateWord() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < WORD_LENGTH; i++) {
            char c = (char) (RANDOM.nextInt(26) + 'a');
            sb.append(c);
        }
        return sb.toString();
    }

}

