using System;
using System.Data;
using System.Data.SqlClient;

namespace GraduationDataReport
{
    class Program
    {
        static void Main(string[] args)
        {
            // 连接到XYZ学区数据库中的graduation_data表
            SqlConnection connection = new SqlConnection("Data Source=xyz_school_district.db");
            connection.Open();
            SqlCommand command = new SqlCommand();
            command.Connection = connection;

            // 执行SQL查询以检索所需数据
            command.CommandText = @"
