scores = zeros(length(synonyms_list), 1);
for i = 1:length(synonyms_list)
    score = strcmp(synonyms_list{i}, synonyms.pristine);
    if score == 0
        score = 1 - levenshtein(synonyms_list{i}, 'pristine') / max(length(synonyms_list{i}), length('pristine'));
    end
    scores(i) = score;
end

% 返回前五个同义词
[sorted_scores, idx] = sort(scores, 'descend');
