    <meta charset="UTF-8">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Tank Game</title>
    <style>
        #gameBoard {
            position: relative;
            background-color: lightgray;
            width: 800px;
            height: 500px;
            border: 2px solid black;
            overflow: hidden;
        }
        #tank {
            position: absolute;
            width: 50px;
            height: 50px;
            background-color: blue;
            left: 0;
            top: 0;
        }
    </style>
</head>
<body>

    <div id="gameBoard">
        <div id="tank"></div>
    </div>

    <script>
        const tank = document.getElementById('tank');
        const gameBoard = document.getElementById('gameBoard');

        function moveTank(event) {
            const tankRect = tank.getBoundingClientRect();
            const gameBoardRect = gameBoard.getBoundingClientRect();
            const offset = 10;

            switch (event.key) {
                case "ArrowUp":
                    if (tankRect.top - offset > gameBoardRect.top) {
                        tank.style.top = `${tank.offsetTop - offset}px`;
                    }
                    break;
                case "ArrowDown":
                    if (tankRect.bottom + offset < gameBoardRect.bottom) {
                        tank.style.top = `${tank.offsetTop + offset}px`;
                    }
                    break;
                case "ArrowLeft":
                    if (tankRect.left - offset > gameBoardRect.left) {
                        tank.style.left = `${tank.offsetLeft - offset}px`;
                    }
                    break;
                case "ArrowRight":
                    if (tankRect.right + offset < gameBoardRect.right) {
                        tank.style.left = `${tank.offsetLeft + offset}px`;
                    }
                    break;
                default:
                    break;
            }
        }

        document.addEventListener('keydown', moveTank);
    </script>
</body>
</html>
```

