  setTimeout(() => {
    mouse.style.display = 'none';
    if (gameTimer) { // 游戏进行中
      showMouse(); // 继续显示地鼠
      scoreValue--; // 未打中扣1分
      score.innerText = scoreValue;
    }
  }, 1000);
