    power_on_ = false;
    cout << name_ << "已关机" << endl;
  }

  // 执行操作
  virtual void Execute() = 0;

  // 获取产品名称
  string GetName() const { return name_; }
};
// 空调产品类
class AirConditioner : public HomeAppliance {
public:
  AirConditioner(string name) : HomeAppliance(name) {}

  ~AirConditioner() {}

  // 执行制冷操作
  void Execute() override {
    if (!power_on_) {
      cout << name_ << "未开机，无法执行制冷操作" << endl;
      return;
    }

    cout << name_ << "正在执行制冷操作" << endl;
  }
};
// 洗衣机产品类
class Washer : public HomeAppliance {
public:
  Washer(string name) : HomeAppliance(name) {}

  ~Washer() {}

  // 执行洗涤操作
  void Execute() override {
    if (!power_on_) {
      cout << name_ << "未开机，无法执行洗涤操作" << endl;
      return;
    }

    cout << name_ << "正在执行洗涤操作" << endl;
  }
};
// 家电产品集合类
class HomeApplianceCollection {
private:
  vector<HomeAppliance*> appliances_; // 产品集合

public:
  HomeApplianceCollection() {}

  ~HomeApplianceCollection() {
    for (auto app : appliances_) {
      delete app;
    }
  }

  // 添加产品
  void Add(HomeAppliance* app) {
    appliances_.push_back(app);
    cout << app->GetName() << "已加入家电集合" << endl;
  }

  // 打开所有电源
  void PowerOnAll() {
    for (auto app : appliances_) {
      app->PowerOn();
    }

    cout << "所有家电已开机" << endl;
  }

  // 关闭所有电源
  void PowerOffAll() {
    for (auto app : appliances_) {
      app->PowerOff();
    }

    cout << "所有家电已关机" << endl;
  }

  // 执行所有产品的操作
  void ExecuteAll() {
    cout << "依次执行所有家电的操作：" << endl;
    for (auto app : appliances_) {
      app->Execute();
    }
  }
};
```
